{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A practical whole-person guide</title>
  <meta name="description" content="Practical, integrative coaching and care planning that connects daily habits, rhythms, and health priorities. Educational — not prescriptive." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <div class="brand">
        <svg class="logo" width="44" height="44" viewBox="0 0 44 44" aria-hidden="true"><rect width="44" height="44" rx="8" fill="#2F6B4A"></rect><circle cx="22" cy="16" r="6" fill="#FFF" opacity="0.9"></circle></svg>
        <div class="brand-text">
          <div class="name">{{BUSINESS_NAME}}</div>
          <div class="sub">Practical integrative guidance</div>
        </div>
      </div>
      <nav class="nav">
        <a href="/index.html">Home</a>
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Conditions</a>
        <a href="/approach.html">Method</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">Meet</a>
        <a href="/book.html">Schedule</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Map what matters — then move forward with clear next steps</h1>
          <p class="lead">A pragmatic, integrative approach for people balancing health, work, and family. We help you sort priorities, choose simple habits, and plan measurable follow-ups.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
            <button id="open-inventory" class="btn ghost">Try the whole-person inventory</button>
            <button id="open-try" class="btn ghost">Try a guided practice</button>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg viewBox="0 0 600 400" class="pattern-bg"><defs><pattern id="p" x="0" y="0" width="60" height="60" patternUnits="userSpaceOnUse"> <rect width="60" height="60" fill="#F6FBF8"/> <path d="M0 30 Q15 10 30 30 T60 30" stroke="#E6F1EA" stroke-width="2" fill="none"/></pattern></defs><rect width="100%" height="100%" fill="url(#p)"/></svg>
        </div>
      </div>
    </section>

    <section id="diagnostic" class="section diagnostic">
      <div class="wrap">
        <h2>Whole-person inventory</h2>
        <p class="muted">Check the areas that feel most active or pressing. The tool will produce a suggested consultation agenda and a follow-up cadence tailored to what you mark.</p>

        <form id="inventory-form" class="inventory">
          <div class="grid">
            <label><input type="checkbox" name="area" value="Sleep" data-weight="2" /> Sleep & recovery</label>
            <label><input type="checkbox" name="area" value="Movement" data-weight="2" /> Movement & function</label>
            <label><input type="checkbox" name="area" value="Nutrition" data-weight="2" /> Nutrition & digestion</label>
            <label><input type="checkbox" name="area" value="Stress" data-weight="3" /> Stress & mood
            </label>
            <label><input type="checkbox" name="area" value="Relationships" data-weight="1" /> Relationships & social rhythm</label>
            <label><input type="checkbox" name="area" value="Purpose" data-weight="1" /> Meaning, work, identity</label>
            <label><input type="checkbox" name="area" value="Environment" data-weight="1" /> Environment & daily context</label>
            <label><input type="checkbox" name="area" value="Symptoms" data-weight="3" /> Active symptoms or flare
            </label>
            <label><input type="checkbox" name="area" value="Medications" data-weight="2" /> Medications & medical history</label>
          </div>

          <div class="form-row">
            <label for="notes">Brief notes (optional)</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Any immediate concerns or context to share..."></textarea>
          </div>

          <div class="form-actions">
            <button type="button" id="generate-agenda" class="btn primary">Generate suggested agenda</button>
            <button type="button" id="save-summary" class="btn ghost">Save summary locally</button>
          </div>
        </form>

        <div id="agenda-output" class="agenda-output" aria-live="polite"></div>
      </div>
    </section>

    <section id="plan" class="section plan">
      <div class="wrap">
        <h2>How we shape a plan</h2>
        <p class="muted">Plans are framed as practical rhythms: an initial assessment followed by short cycles of focused work and periodic reflections.</p>

        <div class="cards">
          <article class="card">
            <h3>Gateway Consult</h3>
            <p>One structured 60–90 minute assessment focused on the most pressing areas you select. Agenda produced from the inventory is used as a map during the visit.</p>
          </article>
          <article class="card">
            <h3>Rhythm Track</h3>
            <p>Flexible 30–45 minute follow-ups in short blocks (4–8 weeks) for habit building, tracking, and stepwise adjustments.</p>
          </article>
          <article class="card">
            <h3>Maintenance Check-ins</h3>
            <p>Lower-touch monthly reviews to keep momentum and adapt goals as life shifts.</p>
          </article>
        </div>

        <div class="plan-cta">
          <a class="btn primary" href="/book.html">Book a Gateway Consult</a>
          <a class="btn ghost" href="/approach.html">Learn the method</a>
        </div>
      </div>
    </section>

    <section id="micro_habits" class="section micro-habits">
      <div class="wrap">
        <h2>Small practices that add up</h2>
        <p class="muted">A curated set of brief, evidence-aware practices you can try in daily life. These are educational suggestions — not medical directives.</p>

        <ul class="habits">
          <li><strong>2-minute evening review</strong> — note one win and one adjustment for tomorrow.</li>
          <li><strong>Movement pause</strong> — three 3-minute movement breaks in your day.</li>
          <li><strong>Micro-nutrition check</strong> — a simple protein+vegetable snack mid-afternoon.</li>
          <li><strong>Breathing reset</strong> — diaphragmatic breathing for 2–4 minutes (use the guided practice).</li>
        </ul>

        <div class="micro-actions">
          <button id="open-try-2" class="btn primary">Try a guided exercise</button>
          <a class="btn ghost" href="/services.html">See suggested supports</a>
        </div>
      </div>
    </section>

    <section id="pricing" class="section pricing">
      <div class="wrap">
        <h2>Offers and investment</h2>
        <p class="muted">Framed as plans that reflect intensity and support rhythm rather than rigid tiers. Educational and transparent pricing.</p>

        <div class="price-grid">
          <div class="price">
            <h3>Intro Gateway</h3>
            <div class="cost">$175</div>
            <p>Single comprehensive consultation (60–75 min) with a follow-up summary and action checklist.</p>
            <a class="btn" href="/book.html">Book Intro</a>
          </div>
          <div class="price featured">
            <h3>Core Stewardship</h3>
            <div class="cost">$320 / 6 weeks</div>
            <p>Two-way support: initial consult + four 30-min follow-ups across 6 weeks, habit tools, and tracking prompts.</p>
            <a class="btn primary" href="/pricing.html">Explore Core</a>
          </div>
          <div class="price">
            <h3>Guided Cohort</h3>
            <div class="cost">Custom</div>
            <p>Group-based learning and shared accountability with periodic individual check-ins. Contact to learn more.</p>
            <a class="btn" href="/contact.html">Inquire</a>
          </div>
        </div>

      </div>
    </section>

    <section id="cta" class="section cta">
      <div class="wrap">
        <h2>Ready to start?</h2>
        <p class="muted">Schedule a Gateway Consult to get a working agenda built from your own priorities.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Serving {{CITY}}, {{STATE}}</div>
      </div>
      <div>
        <div>{{PHONE}}</div>
        <div><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <div class="small-print muted">Educational resources only. Not a replacement for medical care. For urgent medical concerns, contact local emergency services or your clinician.</div>
    </div>
  </footer>

  <!-- Guided practice modal -->
  <div id="practice-modal" class="modal" role="dialog" aria-hidden="true" aria-labelledby="practice-title">
    <div class="modal-content">
      <button class="modal-close" id="close-practice">×</button>
      <h3 id="practice-title">Guided practice: breathe, reflect, set intention</h3>
      <div id="practice-stage" class="practice-stage">
        <div class="visual">
          <svg id="breath-svg" viewBox="0 0 200 200"><circle cx="100" cy="100" r="60" fill="#E9F6EE" stroke="#2F6B4A" stroke-width="4"/></svg>
        </div>
        <div class="stage-text" id="stage-text">Ready to begin?</div>
        <div class="controls">
          <button id="practice-start" class="btn primary">Start</button>
          <button id="practice-skip" class="btn ghost">Skip</button>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
